 * stay byte-for-byte unchanged. Following the Mobile Horizontal-Overflow
 * contract, no horizontal-scroll escape hatch is introduced: content WRAPS.
 *
 * `min-width: 0` is the flex/grid blowout guard (a wide tinted lane child can
 * otherwise pin the column wider than the viewport); `max-width: 100%` caps
 * the lane to the column. */
#flow-view .flow-conversation .conv-record,
#history-view .history-detail .conv-record {
  min-width: 0;
  max-width: 100%;
}
/* The status row is an inline-flex pill; let it wrap and break a long step
 * label rather than forcing a horizontal scroll. */
#flow-view .step-status-row,
#history-view .step-status-row {
  flex-wrap: wrap;
  min-width: 0;
  max-width: 100%;
}
#flow-view .step-status-row .step-status-text,
#history-view .step-status-row .step-status-text {
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}

/* -- idle reply placeholder: shrink so it fits one line (problem 2) ------ *
 * The idle "可先草拟回复,或点 ✎ 插话…" placeholder rides the 16px form-field
 * floor (the iOS-zoom guard above), which on a phone wraps to two lines in the
 * default single-line (collapsed) textarea. Shrink ONLY the placeholder so the
 * hint fits one line; the textarea's own 16px input text is left untouched, so
 * real typing keeps the iOS-zoom guard and the normal input size. Paired with
 * the shortened placeholder string (app.js). Desktop is unaffected. */
#flow-reply-input::placeholder {
  font-size: 13px;
}

